<label class="check-label"><input type="checkbox" name="is_active" value="1" <?= !empty($form['is_active']) ? 'checked' : '' ?>> Çalışan ve giriş hesabı aktif</label><button type="submit" class="btn btn-lumera"><?= $edit ? 'Değişiklikleri kaydet' : 'Çalışan oluştur' ?></button></form></section></div>
